export type ChecklistItem = { id: string; title: string; ask: string; keywords: string[]; seedRef: string };
export type ModelAnswer = { id: string; verdict: "present" | "absent" | "unclear"; quote: string; explanation: string };
export type ReviewStatus = "verified_present" | "unverified_claim" | "not_found" | "unclear";
export type ReviewResult = {
  id: string;
  title: string;
  seedRef: string;
  status: ReviewStatus;
  quote: string;
  explanation: string;
  conflict: boolean;
  keywordHits: string[];
  chunksReviewed: number;
  chunksTotal: number;
  truncated: boolean;
};
export type Review = { results: ReviewResult[]; chunksReviewed: number; chunksTotal: number; truncated: boolean; failedChunks: number };
export const CHECKLIST: ChecklistItem[];
export const CHECKLIST_IDS: string[];
export const CHUNK_CHARS: number;
export const MAX_CHUNKS: number;
export const REVIEW_SYSTEM: string;
export const STATUS_LABEL: Record<ReviewStatus, string>;
export function normalizeForMatch(text: unknown): string;
export function quoteInDocument(quote: unknown, normalizedDoc: string): boolean;
export function chunkDocument(text: unknown, size?: number, maxChunks?: number): { chunks: string[]; truncated: boolean };
export function buildUserPrompt(chunk: string, itemIds: string[], index?: number, total?: number): string;
export function parseModelOutput(raw: unknown): ModelAnswer[];
export function verifyAndMerge(docText: string, perChunk: { chunk: string; answers: ModelAnswer[] }[], meta?: { truncated?: boolean; totalChunks?: number }): ReviewResult[];
export function reviewDocument(text: string, call: (chunk: string, itemIds: string[], index: number, total: number) => Promise<string>, opts?: { itemIds?: string[] }): Promise<Review>;
export function reportToText(review: Review): string;
export type RedactionInfo = { counts: Record<string, number>; total: number; summary: string };
export function reviewDocumentRedacted(text: string, call: (chunk: string, itemIds: string[], index: number, total: number) => Promise<string>, opts?: { extraTerms?: string[]; itemIds?: string[] }): Promise<Review & { redaction: RedactionInfo }>;
